// Build the translation prompt from the incoming post payload.
// The webhook nests the POST body under `.body`; fall back to the root for
// manual test executions.
const input = $input.first().json;
const data = input.body ?? input;

const sourceLang = data.sourceLang === 'en' ? 'en' : 'de';
const targetLang = data.targetLang === 'de' ? 'de' : (data.targetLang || 'en');
const names = { de: 'German', en: 'English' };

const system = [
  `You are a professional translator for Leinss Consulting, a business-process automation consultancy serving German SMEs.`,
  `Translate the blog post from ${names[sourceLang]} to ${names[targetLang]}.`,
  `Rules:`,
  `- Preserve ALL Markdown structure exactly: headings, lists, tables, blockquotes, links, and fenced code blocks. Translate prose only — never translate code, identifiers, or URLs.`,
  `- Keep the tone professional, clear, and benefit-oriented; match the register of the source.`,
  `- Translate tags into idiomatic lowercase-hyphen slugs in the target language where a natural equivalent exists; keep universal terms unchanged (product names, 'roi', 'n8n', 'ai', 'crm').`,
  `- Do not add, remove, or summarise content.`,
  `Return ONLY a valid JSON object with this exact shape and nothing else:`,
  `{"title": string, "description": string, "tags": string[], "body": string}`,
  `No markdown fences, no commentary.`
].join('\n');

const userPayload = {
  title: data.title || '',
  description: data.description || '',
  tags: Array.isArray(data.tags) ? data.tags : [],
  body: data.body || ''
};

return [{
  json: {
    system,
    userContent: JSON.stringify(userPayload),
    model: 'claude-sonnet-4-6',
    max_tokens: 8000
  }
}];

// Extract the model's text output and parse the strict-JSON translation.
const res = $input.first().json;
let text = '';
if (Array.isArray(res.content)) {
  text = res.content.map((c) => c.text || '').join('');
} else if (typeof res === 'string') {
  text = res;
}
text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('LLM did not return valid JSON: ' + text.slice(0, 200));
}

return [{
  json: {
    title: parsed.title,
    description: parsed.description,
    tags: Array.isArray(parsed.tags) ? parsed.tags : [],
    body: parsed.body
  }
}];
